#include <stdio.h>
#include <stdlib.h>

struct node {
    int v;
    struct node *next;
};

int main(void)
{
    struct node *head = NULL;

    for (int i = 1; i <= 4; i++) {
        struct node *n = malloc(sizeof *n);
        n->v = i * i;
        n->next = head;
        head = n;
    }
    for (struct node *p = head; p != NULL; p = p->next)
        printf("%d ", p->v);
    printf("\n");
    while (head != NULL) {
        struct node *t = head->next;
        free(head);
        head = t;
    }
    return 0;
}

