#include <stdio.h>

int main(void)
{
    FILE *f = fopen("n.txt", "w");
    int x, sum = 0, count = 0;

    for (int i = 1; i <= 4; i++)
        fprintf(f, "%d\n", i * 10);
    fclose(f);
    f = fopen("n.txt", "r");
    while (fscanf(f, "%d", &x) == 1) {
        sum += x;
        count++;
    }
    fclose(f);
    printf("%d %d\n", count, sum);
    return 0;
}

