int main(void)
{
    char s[] = "hello, world";
    char *p = s;

    while (*p != '\0') {
        if (*p == ',')
            *p = ';';
        else if (*p >= 'a' && *p <= 'z')
            *p -= 32;
        p++;
    }
    printf("%s\n", s);
