#include <stdio.h>
#include <stdlib.h>

static int cmp(const void *a, const void *b)
{
    return *(const int *) b - *(const int *) a;
}

int main(void)
{
    int v[5] = {3, 9, 1, 7, 5};

    qsort(v, 5, sizeof(int), cmp);
    for (int i = 0; i < 5; i++)
        printf("%d ", v[i]);
