}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    const char *s = "C99 is Fun!";
    int up = 0, digits = 0, spaces = 0;

    for (const char *p = s; *p != '\0'; p++) {
        if (isupper((unsigned char) *p))
            up++;
        if (isdigit((unsigned char) *p))
            digits++;
        if (isspace((unsigned char) *p))
            spaces++;
    }
    printf("%d %d %d\n", up, digits, spaces);
    return 0;
}

